package one

import "testing"

func TestNativeTyping(t *testing.T) {
	if Quote() != "中文😀" { t.Fatalf("Quote = %q", Quote()) }
	if Cases(1) != "one" || Cases(2) != "other" { t.Fatal("case routing") }
	if Raw() != "prefix\n    payload\nsuffix" { t.Fatalf("Raw = %q", Raw()) }
	if RawPath != `C:\` || Rune != '界' { t.Fatal("literal content changed") }
	if SameFile() != 2 || SecondFile() != 3 || ReadValue() != "value" { t.Fatal("Go semantics") }
	Nested(); Call(); Align()
}

